import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const [user, setUser] = useState({
    name: "User",
    email: "user@email.com"
  });

  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("user"));
    if (savedUser) setUser(savedUser);
  }, []);

  const detectSource = (transactions) => {
    if (!transactions || transactions.length === 0) return "Not uploaded";

    const text = transactions.map(t => t.description?.toLowerCase()).join(" ");

    if (text.includes("gpay") || text.includes("google pay")) return "GPay";
    if (text.includes("phonepe")) return "PhonePe";
    if (text.includes("paytm")) return "Paytm";
    if (text.includes("upi")) return "UPI Statement";

    return "Bank Statement";
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      setTransactions(data.transactions || []);
      setType(detectSource(data.transactions));

      const history = JSON.parse(localStorage.getItem("history")) || [];

      history.unshift({
        date: new Date().toLocaleString(),
        type: detectSource(data.transactions),
        count: data.transactions?.length || 0,
        transactions: data.transactions || []
      });

      localStorage.setItem("history", JSON.stringify(history));

    } catch (err) {
      alert("Error processing statement");
    }

    setLoading(false);
  };

  const deleteHistory = (index) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(index, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("history");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>

            {/* ✨ PREMIUM SUBTITLE */}
            <div style={{
              fontSize: "12px",
              letterSpacing: "1.2px",
              opacity: "0.65",
              marginTop: "-4px",
              fontWeight: "500"
            }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions" style={{
            display: "flex",
            alignItems: "center",
            gap: "20px"
          }}>
            
            <div className="tabs" style={{ display: "flex", gap: "16px" }}>
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            {/* PROFILE ICON */}
            <div style={{ position: "relative" }}>
              <div
  onClick={() => setShowProfile(!showProfile)}
  style={{
    width: "40px",
    height: "40px",
    borderRadius: "50%",
    background: "linear-gradient(135deg, #4f6df5, #6a85ff)",
    color: "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontWeight: "600",
    cursor: "pointer"
  }}
>
  {profile.name.charAt(0).toUpperCase()}
</div>

              {showProfile && (
                <div style={{
                  position: "absolute",
                  top: "50px",
                  right: "0",
                  width: "250px",
                  background: "#fff",
                  borderRadius: "12px",
                  padding: "16px",
                  boxShadow: "0 10px 25px rgba(0,0,0,0.15)",
                  zIndex: 100
                }}>
                  <h4 style={{ marginBottom: "10px" }}>Profile</h4>

                  <input
                    value={user.name}
                    onChange={(e) =>
                      setUser({ ...user, name: e.target.value })
                    }
                    style={{ width: "100%", marginBottom: "10px" }}
                  />

                  <input
                    value={user.email}
                    onChange={(e) =>
                      setUser({ ...user, email: e.target.value })
                    }
                    style={{ width: "100%", marginBottom: "10px" }}
                  />

                  <button
                    onClick={() => {
                      localStorage.setItem("user", JSON.stringify(user));
                      setShowProfile(false);
                    }}
                  >
                    Save
                  </button>
                </div>
              )}
            </div>

            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>

          </div>
        </div>

        {/* HERO */}
        <div className="hero">
          <h1 style={{ fontWeight: "700" }}>
            Welcome, <span style={{ color: "#4f7cff" }}>{user.name}</span>
          </h1>
        </div>

        {/* ================= OVERVIEW ================= */}
        {activeTab === "overview" && (
          <>
            {/* KPI */}
            <div className="kpi-grid">
              <div className="kpi-card">
                <h4>Statement Source</h4>
                <p>{type}</p>
              </div>

              <div className="kpi-card">
                <h4>Total Transactions</h4>
                <p>{transactions?.length || 0}</p>
              </div>

              <div className="kpi-card">
                <h4>Status</h4>
                <p>{loading ? "Processing..." : (transactions.length ? "Processed" : "Waiting")}</p>
              </div>
            </div>

            {/* Upload */}
            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />
                  <button onClick={handleUpload}>
                    {loading ? "Processing..." : "Analyze Statement"}
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>AI-powered transaction analysis with categorization</p>
              </div>
            </div>

            {/* Table */}
            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div className="table-wrapper">
                  <table>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                        <th>Amount</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date}</td>
                          <td>{txn.type}</td>
                          <td>{txn.description}</td>
                          <td>{txn.category || "—"}</td>
                          <td>{txn.need_or_want || "—"}</td>
                          <td>₹{txn.amount}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* ================= HISTORY ONLY ================= */}
        {activeTab === "history" && (
          <div className="card table-card">
            <h3>History</h3>

            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Source</th>
                    <th>Count</th>
                    <th style={{ textAlign: "right" }}>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {(JSON.parse(localStorage.getItem("history")) || []).map((h, i) => (
                    <tr key={i}>
                      <td>{h.date}</td>
                      <td>{h.type}</td>
                      <td>{h.count}</td>

                      <td style={{
                        display: "flex",
                        justifyContent: "flex-end",
                        gap: "10px"
                      }}>
                        <button onClick={() => {
                          setTransactions(h.transactions || []);
                          setActiveTab("overview");
                        }}>
                          View
                        </button>

                        <button onClick={() => deleteHistory(i)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
